from sqlalchemy import text


class AuditLogger:
    def record_entry(self, conn, action: str, username: str) -> None:
        query = text(
            "INSERT INTO audit_log (action, username) VALUES (:action, :username)"
        )
        params = {
            "action": action,
            "username": username,
        }
        conn.execute(query, params)
